        countMin:function(time){
            time = this.countSec(time);

            var minute = parseInt(time / 60);
            var sec = parseInt(time - (minute * 60));

            var minTxt = minute + '';
            if(minute < 10) minTxt = '0' + minute;

            var secTxt = sec + '';
            if(sec < 10) secTxt = '0' + sec;

            var showTime = minTxt + ':' + secTxt;
            return showTime;
        },

        countSec:function(time){
            var tempTime = Math.floor(time);
            var showTime = tempTime;

            if(tempTime > 0){
                var checkTime = time % tempTime;

                if(checkTime > 0){
                    // console.log(checkTime)
                    showTime = tempTime + 1;
                }
            } else {
                if(time > tempTime){
                    showTime += 1;
                } else {
                    showTime = 0;
                }
            }

            return showTime;
        },

        writeThousands:function(score){
            var showScore = score + '';

            if(score >= 1000){
                var count = 0;
                var countScore = showScore;
                showScore = '';
                for(var a = countScore.length - 1; a >= 0; a--){
                    var toShow = countScore[a];
                    if(count % 3 == 0 && a < countScore.length - 1){
                        toShow += ',';
                        count = 0;
                    }

                    var tempShow = toShow + showScore;
                    showScore = tempShow;

                    count++;
                }
            }

            return showScore;
        },

        wordWrapText:function(text, wordWrapWidth, context){
            context = context ? context : ig.system.context;

            var result = '';
            var separator = ' ';
            var lines = text.split('\n');
            for(var a = 0; a < lines.length; a++){
                var line = lines[a];
                var words = line.split(separator);
                var lineWidth = 0;

                for(var b = 0; b < words.length; b++){
                    var word = words[b];

                    var space = '';
                    if(b > 0){
                        space = separator;
                    }

                    var tempTxt = space + word;
                    var spaceWidth = context.measureText(tempTxt).width;
                    lineWidth += spaceWidth

                    if(lineWidth >= wordWrapWidth){
                        tempTxt = '\n' + word;
                        lineWidth = context.measureText(word).width;
                    } 

                    result += tempTxt;
                }

                if(a < lines.length - 1){
                    result += '\n';
                }
            }
            
            return result;  
        },

        drawGradientText:function(text, x, y, fontSize, fontType, colorStoppers){
            var ctx = ig.system.context;
            ctx.save()

            fontSize = fontSize ? fontSize : 70;
            var font = fontType ? fontType : fonts.font1
            ctx.font = fontSize + 'px ' + font;
            ctx.textAlign = 'center'
            ctx.textBaseline = 'alphabetic'

            if(!colorStoppers){
                var colorIn = '#fdf764'
                var colorOut = '#bc6c1c'
                var colorTop = '#ffffdf'
                var colorStoppers = [
                    {stopper:0.0, color:colorTop},
                    {stopper:0.2, color:colorIn},
                    {stopper:0.4, color:colorIn},
                    {stopper:0.5, color:colorOut},
                    {stopper:0.6, color:colorIn}
                ]
            }

            var title = text;
            var titleX = x                      //middle
            var titleY = y                      //top
            var titleW = ctx.measureText(title).width

            ctx.translate(titleX, titleY)

            ctx.strokeStyle = '#ffffd6'
            ctx.lineWidth = 1.5
            ctx.strokeText(title, 0, (fontSize*0.8))

            ctx.shadowColor = 'rgba(0, 0, 0, 0.6)'
            ctx.shadowBlur = 5
            ctx.shadowOffsetX = 0
            ctx.shadowOffsetY = 6

            var offX1 = - (titleW/2);
            var offY1 = -3;
            var offX2 = offX1
            var offY2 = offY1 + fontSize

            var gradient = ctx.createLinearGradient(offX1, offY1, offX2, offY2);   
            for(var a = 0; a < colorStoppers.length; a++){
                var stopperData = colorStoppers[a];
                gradient.addColorStop(stopperData.stopper, stopperData.color)
            } 

            ctx.fillStyle = gradient;

            // ctx.fillRect(offX1, offY1, titleW, fontSize)

            ctx.fillText(title, 0, (fontSize*0.8))

            ctx.restore()
        },

        fpsCount: function(){
            if(!this.fpsTimer){
                this.fpsTimer = new ig.Timer(1);
            }
            if(this.fpsTimer && this.fpsTimer.delta() < 0){
                if(this.fpsCounter != null){
                    this.fpsCounter ++ ;
                }else{
                    this.fpsCounter = 0 ;
                }
            }else{
                ig.game.fps = this.fpsCounter ;
                this.fpsCounter = 0 ;
                this.fpsTimer.reset();
            }
        },

